create policy "Authorised users can create incident media" on public.incident_media for insert to authenticated with check (exists (select 1 from public.incidents i where i.id = incident_id and (i.submitted_by = (select auth.uid()) or i.reporter_id = (select auth.uid()) or i.assigned_to = (select auth.uid()) or public.is_super_admin((select auth.uid())) or (public.is_campus_admin((select auth.uid())) and i.campus = public.get_user_campus((select auth.uid()))))));